    target = text.casefold()
    predicates = [RDFS.label, SKOS.prefLabel, QUDT.symbol, QUDT.ucumCode, QUDT.uneceCommonCode]
    for predicate in predicates:
        for subj, _, lit in self.graph.triples((None, predicate, None)):
