def _extract_individuals(g: Graph, namespace: str) -> list[ExtractedIndividual]:
    """Extract all owl:NamedIndividual subjects in the ontology namespace."""
    individuals = []
    for ind_iri in g.subjects(RDF.type, OWL.NamedIndividual):
