def _uri_is_subject_in_rdf(uri: str, rdf: rdflib.Graph, force: bool):
    """Check whether uri is a subject in the rdf.

    Args:
        rdf: The RDF graph
        uri: Uri of the object
        force: Toggle raising an error (force=False) or just a warning (force=True)
