    preferred: List[str] = []
    fallback: List[str] = []
    for row in results:
        t_uri = str(row.t)
        if t_uri.rstrip("/").endswith("/SynthesisStep"):
            fallback.append(t_uri)
        else:
            preferred.append(t_uri)
    if preferred:
        return _local_name(preferred[0])
    if fallback:
        # When the only type is the generic SynthesisStep, return a safer placeholder 'Step'
        return "Step"
    return "Step"

