def query_step_details_all_fields(graph: Graph, step_uri: str) -> Dict[str, Any]:
    """Collect all direct properties of a step, preferring labels for object IRIs.

    Output shape: { <StepTypeLabel>: { <fieldName>: value or [values] } }
    """
    step_type = query_step_type_label(graph, step_uri)

    # Query all outgoing properties except rdf:type
    q_props = """
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
    PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
    SELECT DISTINCT ?p ?o ?olabel WHERE {
      ?s ?p ?o .
      FILTER(?s = ?S)
      FILTER(?p != rdf:type)
      OPTIONAL { ?o rdfs:label ?olabel }
    }
    """
    results = graph.query(q_props, initBindings={"S": URIRef(step_uri)})

    fields: Dict[str, Any] = {}
    for row in results:
        p_uri = str(row.p)
        o = row.o
        o_label = str(row.olabel) if row.olabel else ""
        field_name = _camelize(_local_name(p_uri))

        # Normalize the object
        if isinstance(o, URIRef):
            # Prefer human label when available; drop IRIs from final step field values
            value = o_label or ""
        else:
            value = str(o)

        if field_name in fields:
            # Merge: list-append when already present
            if isinstance(fields[field_name], list):
                fields[field_name].append(value)
            else:
                fields[field_name] = [fields[field_name], value]
        else:
            fields[field_name] = value

    # Do not include raw URI in the output; keep only human-friendly fields

    # Attempt to surface the main rdfs:label for the step itself
    q_label = """
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
    SELECT ?label WHERE { ?s rdfs:label ?label . FILTER(?s = ?S) }
    """
    labels = [str(r.label) for r in graph.query(q_label, initBindings={"S": URIRef(step_uri)})]
    if labels:
        # If multiple labels, keep them all
        fields["label"] = labels if len(labels) > 1 else labels[0]

    # Deduplicate object lists by label only
    for key, value in list(fields.items()):
        if isinstance(value, list):
            seen: List[str] = []
            merged_list: List[str] = []
            for it in value:
                lbl = it if isinstance(it, str) else ""
                if lbl and lbl not in seen:
                    seen.append(lbl)
                    merged_list.append(lbl)
            if merged_list:
                fields[key] = merged_list

    return {step_type: fields}

def query_synthesis_inputs(graph: Graph, synthesis_uri: str) -> List[Dict[str, any]]:
    """Find chemicals for a synthesis via direct input links or Add-step links."""
    query = """
    PREFIX ontosyn: <https://www.theworldavatar.com/kg/OntoSyn/>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

    SELECT DISTINCT ?chemical ?label ?amount ?altName
    WHERE {
        {
            ?synthesis ontosyn:hasChemicalInput ?chemical .
        }
        UNION
        {
            ?synthesis ontosyn:hasSynthesisStep ?step .
            ?step ontosyn:hasAddedChemicalInput ?chemical .
        }
        OPTIONAL { ?chemical rdfs:label ?label }
        OPTIONAL { ?chemical ontosyn:hasAmount ?amount }
        OPTIONAL { ?chemical ontosyn:hasAlternativeNames ?altName }
    }
    """
    results = graph.query(query, initBindings={"synthesis": URIRef(synthesis_uri)})

    # Group by chemical URI to collect all alternative names
    grouped: Dict[str, Dict[str, any]] = {}
    for row in results:
        chem_uri = str(row.chemical) if row.chemical else ""
        if chem_uri not in grouped:
            grouped[chem_uri] = {
                "uri": chem_uri,
                "label": str(row.label) if row.label else "N/A",
                "amount": str(row.amount) if row.amount else "N/A",
                "alternative_names": []
            }
        # Collect alternative names
        if row.altName:
            alt = str(row.altName)
            if alt and alt not in grouped[chem_uri]["alternative_names"]:
                grouped[chem_uri]["alternative_names"].append(alt)

    return list(grouped.values())

