                    namespaces['rdfs'].label,
                    rdflib.term.Literal(value['label'])
                ))

            if predicate_type['uri'] in [
                'http://purl.org/dc/elements/1.1/creator',
                'http://purl.org/dc/elements/1.1/contributor',
            ]:
                if value.get('uri', None) is not None:
